import type { LearnerState, SrsCard } from "../../domain/shared/types";
import { INITIAL_LEARNER_STATE } from "../../domain/shared/types";
import { mergeLearnerStates } from "./MergeService";
import { validateLearnerState } from "./Validation";

interface LegacySrsData {
	easeFactor: number;
	interval: number;
	repetitions: number;
	learningStep?: number | null;
	nextReviewDate: string;
	lastReviewDate: string | null;
	lapseCount?: number;
}

function migrateSrsCard(card: SrsCard): void {
	const srs = card.srs as LegacySrsData;
	if (srs.learningStep === undefined) {
		srs.learningStep = null;
	}
	if (srs.lapseCount === undefined) {
		srs.lapseCount = 0;
	}
}

export function migrateState(state: LearnerState): LearnerState {
	for (const card of Object.values(state.cards)) {
		migrateSrsCard(card);
	}
	for (const card of Object.values(state.vocabCards ?? {})) {
		migrateSrsCard(card);
		// Migrate legacy wordThai → promptWord
		const legacy = card as unknown as Record<string, unknown>;
		if ("wordThai" in legacy && !("promptWord" in legacy)) {
			legacy.promptWord = legacy.wordThai;
			delete legacy.wordThai;
		}
	}
	for (const card of Object.values(state.grammarCards ?? {})) {
		migrateSrsCard(card);
	}
	for (const card of Object.values(state.sentenceCards ?? {})) {
		migrateSrsCard(card);
	}
	return state;
}

export interface IStorage {
	load(): LearnerState;
	save(state: LearnerState): void;
	reset(): void;
	exportData(): string;
	importData(json: string): void;
}

export class InMemoryStorage implements IStorage {
	private state: LearnerState = structuredClone(INITIAL_LEARNER_STATE);

	load(): LearnerState {
		return structuredClone(this.state);
	}

	save(state: LearnerState): void {
		this.state = structuredClone(state);
	}

	reset(): void {
		this.state = structuredClone(INITIAL_LEARNER_STATE);
	}

	exportData(): string {
		return JSON.stringify(this.state);
	}

	importData(json: string): void {
		const parsed: unknown = JSON.parse(json);
		if (!validateLearnerState(parsed)) {
			throw new Error("Invalid progress file format");
		}
		this.state = mergeLearnerStates(this.state, parsed as LearnerState);
	}
}

export class LocalStorageAdapter implements IStorage {
	private readonly key: string;

	constructor(key = "thai-srs-state") {
		this.key = key;
	}

	load(): LearnerState {
		if (typeof localStorage === "undefined") {
			return structuredClone(INITIAL_LEARNER_STATE);
		}
		const raw = localStorage.getItem(this.key);
		if (!raw) return structuredClone(INITIAL_LEARNER_STATE);
		const state = JSON.parse(raw) as LearnerState;
		if (!state.vocabCards) {
			state.vocabCards = {};
		}
		if (!state.grammarCards) {
			state.grammarCards = {};
		}
		if (!state.sentenceCards) {
			state.sentenceCards = {};
		}
		if (!state.achievements) {
			state.achievements = [];
		}
		return migrateState(state);
	}

	save(state: LearnerState): void {
		if (typeof localStorage === "undefined") return;
		localStorage.setItem(this.key, JSON.stringify(state));
	}

	reset(): void {
		if (typeof localStorage === "undefined") return;
		localStorage.removeItem(this.key);
	}

	exportData(): string {
		return JSON.stringify(this.load());
	}

	importData(json: string): void {
		const parsed: unknown = JSON.parse(json);
		if (!validateLearnerState(parsed)) {
			throw new Error("Invalid progress file format");
		}
		const merged = mergeLearnerStates(this.load(), parsed as LearnerState);
		this.save(merged);
	}
}
	if (card instanceof SentenceReviewCard) return card.toDTO() as SentenceCard;
	throw new Error(`Unknown card type: ${card.pool}`);
}

export class StorageCardRepository implements CardRepository {
	constructor(private readonly storage: IStorage) {}

	findById(id: string, pool: CardPool): ReviewableCard | null {
		const state = this.storage.load();
		const dict = getCardsDict(state, pool);
		const raw = dict[id];
		if (!raw) return null;
		return toDomain(pool, raw);
	}

	findDue(now: string, pool: CardPool): ReviewableCard[] {
		return this.findAll(pool).filter((card) => card.isDue(now));
	}

	findAll(pool: CardPool): ReviewableCard[] {
		const state = this.storage.load();
		const dict = getCardsDict(state, pool);
		return Object.values(dict).map((raw) => toDomain(pool, raw));
	}

	save(card: ReviewableCard): void {
		const state = this.storage.load();
		this.assignToState(state, card);
		this.storage.save(state);
	}

	saveAll(cards: ReviewableCard[]): void {
		if (cards.length === 0) return;
		const state = this.storage.load();
		for (const card of cards) {
			this.assignToState(state, card);
		}
		this.storage.save(state);
	}

	remove(id: string, pool: CardPool): void {
		const state = this.storage.load();
		const dict = getCardsDict(state, pool);
		delete dict[id];
		this.storage.save(state);
	}

	private assignToState(state: LearnerState, card: ReviewableCard): void {
		const pool = card.pool;
		const dto = cardToDTO(card);
		getCardsDict(state, pool)[card.id] = dto;
	}
}

